import { TranscriptCue, Chapter } from '../types/player';

export const parseVtt = (vtt: string, type: 'caption' | 'description'): TranscriptCue[] => {
  const cues: TranscriptCue[] = [];
  const lines = vtt.replace(/^WEBVTT.*\n/, '').split(/\r?\n/).filter(l => l.trim() !== '');
  let i = 0;
  while (i < lines.length) {
    if (/^\d+$/.test(lines[i])) i++;
    if (/^\d{2}:\d{2}:\d{2}\.\d{3} -->/.test(lines[i])) {
      const [start, end] = lines[i].split(' --> ').map(toSeconds);
      i++;
      let text = '';
      while (i < lines.length && !/^\d{2}:\d{2}:\d{2}\.\d{3} -->/.test(lines[i]) && !/^\d+$/.test(lines[i])) {
        text += (text ? ' ' : '') + lines[i];
        i++;
      }
      cues.push({ start, end, text, type });
    } else {
      i++;
    }
  }
  return cues;
};

export const toSeconds = (s: string) => {
  const [h, m, rest] = s.split(':');
  const [sec, ms] = rest.split(',');
  return parseInt(h) * 3600 + parseInt(m) * 60 + parseInt(sec) + (ms ? parseInt(ms) / 1000 : 0);
};

export const parseChaptersVtt = (vtt: string): Chapter[] => {
  const chapters: Chapter[] = [];
  const lines = vtt.replace(/^WEBVTT.*\n/, '').split(/\r?\n/).filter(l => l.trim() !== '');
  let i = 0;
  while (i < lines.length) {
    if (/^\d+$/.test(lines[i])) i++;
    if (/^\d{2}:\d{2}:\d{2}\.\d{3} -->/.test(lines[i])) {
      const [start, end] = lines[i].split(' --> ').map(toSeconds);
      i++;
      let title = '';
      while (i < lines.length && !/^\d{2}:\d{2}:\d{2}\.\d{3} -->/.test(lines[i]) && !/^\d+$/.test(lines[i])) {
        title += (title ? ' ' : '') + lines[i];
        i++;
      }
      chapters.push({ start, end, title });
    } else {
      i++;
    }
  }
  return chapters;
};

export const formatTime = (sec: number): string => {
  const m = Math.floor(sec / 60);
  const s = Math.floor(sec % 60);
  return `${m}:${s.toString().padStart(2, '0')}`;
};

export const addPlayerStyles = (): () => void => {
  const style = document.createElement('style');
  style.innerHTML = `
    .player-btn:focus {
      outline: 3px solid #1976d2;
      outline-offset: 2px;
      z-index: 2;
    }
  `;
  document.head.appendChild(style);
  return () => { document.head.removeChild(style); };
};