import React from 'react';
import { Transcript } from './Transcript';
import { ChaptersSidebar } from './ChaptersSidebar';

interface PlayerSidebarProps {
  playerState: any;
  cues: any[];
  parsedChapters: any[];
  onChapterClick: (time: number) => void;
}

export const PlayerSidebar: React.FC<PlayerSidebarProps> = ({
  playerState,
  cues,
  parsedChapters,
  onChapterClick
}) => {
  return (
    <>
      {/* Transcript */}
      {playerState.showTranscript && (
        <Transcript 
          cues={cues.filter((cue: any) => cue.type === 'description')}
          currentCueIdx={playerState.currentCueIdx}
          visible={playerState.showTranscript}
        />
      )}

      {/* Chapters Sidebar */}
      {playerState.showChapters && (
        <ChaptersSidebar
          chapters={parsedChapters}
          currentChapterIdx={playerState.currentChapterIdx}
          onChapterClick={onChapterClick}
          visible={playerState.showChapters}
        />
      )}
    </>
  );
};