import React from 'react';
import { TranscriptCue } from '../types/player';

interface TranscriptProps {
  cues: TranscriptCue[];
  currentCueIdx: number;
  visible: boolean;
}

export const Transcript: React.FC<TranscriptProps> = ({ cues, currentCueIdx, visible }) => {
  if (!visible || cues.length === 0) return null;

  return (
    <div
      style={{ 
        marginTop: 16, 
        background: '#f5f5f5', 
        padding: 8, 
        borderRadius: 4, 
        minHeight: 40 
      }}
      aria-live="polite"
      role="region"
      aria-label="Synchronisiertes Transkript"
    >
      <ol style={{ listStyle: 'none', padding: 0, margin: 0 }}>
        {cues.map((cue, idx) => (
          <li
            key={idx}
            aria-current={idx === currentCueIdx ? 'true' : undefined}
            tabIndex={idx === currentCueIdx ? 0 : -1}
            style={{
              background: idx === currentCueIdx ? (cue.type === 'caption' ? '#ffe082' : '#b3e5fc') : 'transparent',
              fontWeight: idx === currentCueIdx ? 'bold' : 'normal',
              color: cue.type === 'caption' ? '#333' : '#0277bd',
              padding: '0 2px',
              borderRadius: 2,
              marginRight: 2,
              outline: idx === currentCueIdx ? '2px solid #1976d2' : 'none',
              display: 'inline-block',
              marginBottom: 2
            }}
          >
            <span aria-label={cue.type === 'caption' ? 'Untertitel' : 'Beschreibung'}>
              {cue.text + ' '}
            </span>
          </li>
        ))}
      </ol>
    </div>
  );
};
