"use client"

import React, { useRef, useEffect, useState } from 'react';
import { FullPlayerProps } from '../types/player';
import { usePlayerState } from '../hooks/usePlayerState';
import { usePlayerEffects } from '../hooks/usePlayerEffects';
import { usePlayerControls } from '../hooks/usePlayerControls';
import { useTranscriptData, useChaptersData } from '../hooks/useVideoData';
import { PlayerControls } from './PlayerControls';
import { PlayerModals } from './PlayerModals';
import { PlayerSidebar } from './PlayerSidebar';
import { formatTime } from '../utils/videoUtils';
import styles from './FullPlayer.module.css';

const FullPlayer: React.FC<FullPlayerProps> = ({ 
  mp4, 
  webm, 
  youtube, 
  vimeo, 
  btag, 
  captions, 
  description, 
  chapters, 
  autoplay = false, 
  muted = true 
}) => {
  // Refs
  const videoRef = useRef<HTMLVideoElement>(null);
  const youtubeContainerRef = useRef<HTMLDivElement>(null);
  const vimeoContainerRef = useRef<HTMLDivElement>(null);
  const hideTimeoutRef = useRef<NodeJS.Timeout | null>(null);

  // Controls visibility state
  const [controlsVisible, setControlsVisible] = useState(false);

  // Hooks
  const playerState = usePlayerState({ autoplay, muted });
  const { cues } = useTranscriptData(description);
  const { parsedChapters } = useChaptersData(chapters);
  
  const playerControls = usePlayerControls({
    videoRef,
    youtubeContainerRef,
    vimeoContainerRef,
    playerState
  });

  usePlayerEffects({
    mp4,
    webm,
    youtube,
    vimeo,
    btag,
    captions,
    description,
    chapters,
    playerState,
    cues,
    parsedChapters,
    videoRef,
    youtubeContainerRef,
    vimeoContainerRef
  });

  // Controls visibility logic
  const showControls = () => {
    setControlsVisible(true);
    if (hideTimeoutRef.current) {
      clearTimeout(hideTimeoutRef.current);
    }
    if (playerState.isPlaying) {
      hideTimeoutRef.current = setTimeout(() => {
        setControlsVisible(false);
      }, 5000);
    }
  };

  const hideControls = () => {
    if (hideTimeoutRef.current) {
      clearTimeout(hideTimeoutRef.current);
    }
    if (playerState.isPlaying) {
      setControlsVisible(false);
    }
  };

  // Event handlers
  const handleMouseMove = () => {
    showControls();
  };

  const handleKeyDown = (e: KeyboardEvent) => {
    showControls();
    
    // Keyboard shortcuts
    switch (e.code) {
      case 'Space':
        e.preventDefault();
        playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay();
        break;
      case 'KeyF':
        playerControls.handleFullscreen();
        break;
      case 'KeyM':
        playerControls.handleMuteToggle();
        break;
    }
  };

  const handlePlayClick = () => {
    playerControls.handlePlay();
    showControls();
  };

  // Setup event listeners
  useEffect(() => {
    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
      if (hideTimeoutRef.current) {
        clearTimeout(hideTimeoutRef.current);
      }
    };
  }, [playerState.isPlaying]);

  // Show controls when paused
  useEffect(() => {
    if (!playerState.isPlaying) {
      setControlsVisible(true);
      if (hideTimeoutRef.current) {
        clearTimeout(hideTimeoutRef.current);
      }
    }
  }, [playerState.isPlaying]);

  const getVideoTypeIcon = () => {
    switch (playerState.playerType) {
      case 'youtube': return '📺';
      case 'vimeo': return '🎥';
      case 'btag': return '🏛️';
      default: return '🎬';
    }
  };

  // Feature availability
  const hasCC = !!captions;
  const hasTranscript = !!description;
  const hasAudioDesc = !!description || playerState.hasAudioTrack;

  return (
    <section aria-label="Barrierefreier Video Player" className={styles.container}>
      <div className={styles.playerSection}>
        
        {/* Video Container */}
        <div 
          className={styles.videoContainer}
          onMouseMove={handleMouseMove}
          onMouseLeave={hideControls}
        >
          {/* Loading Overlay */}
          {playerState.isLoading && (
            <div className={styles.loadingOverlay}>
              <div>Lädt...</div>
            </div>
          )}

          {/* Poster Overlay - Zeige wenn Video nicht läuft */}
          {!playerState.isPlaying && !playerState.isLoading && (
            <div className={styles.posterOverlay} onClick={handlePlayClick}>
              {/* Video Type Icon */}
              <div className={styles.videoTypeIcon}>
                {getVideoTypeIcon()}
              </div>
              
              {/* Play Button */}
              <button className={styles.overlayPlayButton} aria-label="Video abspielen">
                ▶️
              </button>
            </div>
          )}

          {/* Video Element */}
          {(playerState.playerType === 'video' || playerState.playerType === 'btag') && playerState.videoSrc && (
            <video
              ref={videoRef}
              src={playerState.videoSrc}
              className={styles.videoElement}
              controls={false}
              playsInline
              autoPlay={false}
              muted={playerState.isMuted}
            >
              {/* Captions Track */}
              {captions && (
                <track
                  kind="subtitles"
                  src={captions}
                  srcLang="de"
                  label="Deutsche Untertitel"
                  default
                />
              )}
              
              {/* Description Track */}
              {description && (
                <track
                  kind="descriptions"
                  src={description}
                  srcLang="de"
                  label="Audiodeskription"
                />
              )}
              
              {/* Chapters Track */}
              {chapters && (
                <track
                  kind="chapters"
                  src={chapters}
                  srcLang="de"
                  label="Kapitel"
                />
              )}
            </video>
          )}

          {/* YouTube Container */}
          {playerState.playerType === 'youtube' && (
            <div ref={youtubeContainerRef} className={styles.youtubeContainer} />
          )}

          {/* Vimeo Container */}
          {playerState.playerType === 'vimeo' && (
            <div ref={vimeoContainerRef} className={styles.vimeoContainer} />
          )}

          {/* Controls Overlay */}
          <div className={`${styles.controlsOverlay} ${controlsVisible ? styles.visible : ''}`}>
            {/* First Row - Play, Volume, Skip buttons + Fullscreen, PiP */}
            <div className={styles.controlsRow}>
              <div className={styles.leftControls}>
                {/* Play/Pause */}
                <button
                  onClick={() => playerState.isPlaying ? playerControls.handlePause() : playerControls.handlePlay()}
                  className={`${styles.controlButton} ${styles.playPauseButton}`}
                  aria-label={playerState.isPlaying ? 'Pausieren' : 'Abspielen'}
                >
                  {playerState.isPlaying ? '⏸️' : '▶️'}
                </button>

                {/* Volume */}
                <button
                  onClick={playerControls.handleMuteToggle}
                  className={styles.controlButton}
                  aria-label={playerState.isMuted ? 'Ton an' : 'Stumm'}
                >
                  {playerState.isMuted ? '🔇' : '🔊'}
                </button>

                {/* Skip Back */}
                <button
                  onClick={() => playerControls.handleSeek(playerState.currentTime - 10)}
                  className={styles.controlButton}
                  aria-label="10 Sekunden zurück"
                >
                  ⏪
                </button>

                {/* Skip Forward */}
                <button
                  onClick={() => playerControls.handleSeek(playerState.currentTime + 10)}
                  className={styles.controlButton}
                  aria-label="10 Sekunden vor"
                >
                  ⏩
                </button>
              </div>

              <div className={styles.rightControls}>
                {/* Picture in Picture */}
                {playerState.isPiPSupported && (
                  <button
                    onClick={playerControls.handlePiP}
                    className={styles.controlButton}
                    aria-label="Bild-in-Bild"
                  >
                    📺
                  </button>
                )}

                {/* Fullscreen */}
                <button
                  onClick={playerControls.handleFullscreen}
                  className={styles.controlButton}
                  aria-label="Vollbild"
                >
                  ⛶
                </button>
              </div>
            </div>

            {/* Second Row - Settings, Quality, etc. */}
            <div className={styles.controlsRow}>
              <div className={styles.leftControls}>
                {/* Quality */}
                <button
                  className={styles.controlButton}
                  aria-label="Qualität"
                >
                  🎥
                </button>

                {/* Settings */}
                <button
                  className={styles.controlButton}
                  aria-label="Einstellungen"
                >
                  ⚙️
                </button>

                {/* CC */}
                {hasCC && (
                  <button
                    onClick={() => playerState.setShowCC(!playerState.showCC)}
                    className={styles.controlButton}
                    aria-label="Untertitel"
                  >
                    CC
                  </button>
                )}
              </div>
            </div>
          </div>
        </div>

        {/* Progress Bar */}
        <div className={styles.progressBar}>
          <span className={styles.timeDisplay}>
            {formatTime(playerState.currentTime)}
          </span>
          <input
            type="range"
            min={0}
            max={playerState.duration || 1}
            step={0.01}
            value={playerState.currentTime}
            onChange={e => playerControls.handleSeek(Number(e.target.value))}
            aria-label="Fortschritt"
            className={styles.progressSlider}
            style={{
              background: `linear-gradient(to right, #007acc 0%, #007acc ${(playerState.currentTime / playerState.duration) * 100}%, #ddd ${(playerState.currentTime / playerState.duration) * 100}%, #ddd 100%)`
            }}
          />
          <span className={styles.timeDisplay}>
            {formatTime(playerState.duration)}
          </span>
        </div>

        {/* Controls */}
        <PlayerControls
          playerState={playerState}
          playerControls={playerControls}
          hasCC={hasCC}
          hasTranscript={hasTranscript}
          hasAudioDesc={hasAudioDesc}
          hasChapters={!!chapters}
        />

        {/* Sidebar */}
        <PlayerSidebar
          playerState={playerState}
          cues={cues}
          parsedChapters={parsedChapters}
          onChapterClick={playerControls.handleChapterClick}
        />
      </div>

      {/* Modals */}
      <PlayerModals
        playerState={playerState}
        hasCC={hasCC}
        hasTranscript={hasTranscript}
      />
    </section>
  );
};

export default FullPlayer;